html:
{% set amt = (doc.paid_amount or 0) if doc.payment_type=="Pay" else (doc.received_amount or 0) %}
{% set currency = doc.company_currency or frappe.db.get_value("Company", doc.company, "default_currency") %}
{% set company = frappe.get_doc("Company", doc.company) %}

{# Company address (first linked Address) #}
{% set comp_addr_link = frappe.get_all("Dynamic Link",
    filters={"link_doctype":"Company","link_name":doc.company,"parenttype":"Address"},
    fields=["parent"], limit=1) %}
{% set comp_addr = comp_addr_link and frappe.get_doc("Address", comp_addr_link[0].parent) or None %}

{# Payee address (first linked Address for party) #}
{% set payee_name = doc.party_name or doc.party %}
{% set payee_addr_link = frappe.get_all("Dynamic Link",
    filters={"link_doctype":doc.party_type, "link_name":doc.party, "parenttype":"Address"},
    fields=["parent"], limit=1) %}
{% set payee_addr = payee_addr_link and frappe.get_doc("Address", payee_addr_link[0].parent) or None %}

{# Bank Account from Paid From (for outgoing cheque) #}
{% set bank_acc = frappe.get_all("Bank Account",
    filters={"account": doc.paid_from, "company": doc.company},
    fields=["name","bank_account_no","routing_number"], limit=1) %}
{% set bank = bank_acc and bank_acc[0] or {} %}
{% set routing = bank.get("routing_number") or "" %}
{% set account_no = bank.get("bank_account_no") or "" %}

{# Amount in words #}
{% set amt_words = frappe.utils.money_in_words(amt, currency) %}

<style>
  .cheque { font-family: "Inter", Arial, sans-serif; font-size: 11pt; line-height: 1.25; width: 190mm; padding: 10mm 12mm 12mm; }
  .grid { display: grid; grid-template-columns: 62% 38%; gap: 8mm; }
  .muted { color:#444; }
  .bold { font-weight: 600; }
  .line { border-bottom: 1px solid #000; height: 7mm; }
  .pad-sm { margin-top: 3mm; }
  .pad-md { margin-top: 6mm; }
  .right-col .row { margin-bottom: 5mm; }
  .amount-box { font-size: 15pt; font-weight: 700; text-align: right; padding: 4mm; border: 1px solid #000; }
  .signature { text-align: right; margin-top: 18mm; }
  .signature .line { width: 65mm; display: inline-block; vertical-align: bottom; }
  .tiny { font-size: 9pt; }
  /* fine adjustments for your stock — tweak these if needed */
  .cheque { padding-top: 12mm; }
</style>

<div class="cheque">
  <div class="grid">
    <!-- LEFT -->
    <div class="left-col">
      <div class="bold" style="font-size: 13pt;">{{ doc.company }}</div>
      <div class="muted tiny">
        {% if comp_addr %}
          {{ comp_addr.address_line1 }}{% if comp_addr.address_line2 %}, {{ comp_addr.address_line2 }}{% endif %},
          {{ comp_addr.city }}{% if comp_addr.state %}, {{ comp_addr.state }}{% endif %} {{ comp_addr.pincode }}
        {% endif %}
        {% set phone = company.phone_no or company.company_phone %}
        {% if phone %}<br>Phone: {{ phone }}{% endif %}
      </div>

      <div class="pad-md bold">Pay to the Order of:</div>
      <div class="line" style="display:flex; align-items:center; justify-content:space-between;">
        <div style="padding-right:10mm;">{{ payee_name or "" }}</div>
      </div>

      <div class="pad-sm bold">Amount (in words):</div>
      <div class="line" style="display:flex; align-items:center;">
        <div style="padding-right:10mm;">{{ amt_words }}</div>
      </div>

      <div class="pad-md muted">Mailing Address of Payee:</div>
      <div style="margin-left:6mm;">
        <div class="bold">{{ payee_name or "" }}</div>
        {% if payee_addr %}
          <div class="tiny">
            {{ payee_addr.address_line1 }}{% if payee_addr.address_line2 %}, {{ payee_addr.address_line2 }}{% endif %}<br>
            {{ payee_addr.city }}{% if payee_addr.state %}, {{ payee_addr.state }}{% endif %} {{ payee_addr.pincode }}
          </div>
        {% endif %}
      </div>

      <div class="pad-md tiny">
        <span class="bold">Account #:</span> {{ account_no or "—" }} &nbsp;&nbsp;
        <span class="bold">Routing #:</span> {{ routing or "—" }}
      </div>
    </div>

    <!-- RIGHT -->
    <div class="right-col">
      <div class="row">
        <div class="bold">Routing Number</div>
        <div class="tiny">{{ routing or "—" }}</div>
      </div>

      <div class="row">
        <div class="bold">Date</div>
        <div class="tiny">{{ frappe.format_date(doc.posting_date) }}</div>
      </div>

      <div class="row">
        <div class="bold">Memo</div>
        <div class="tiny">{{ doc.memo or doc.remarks or "" }}</div>
      </div>

      <div class="row">
        <div class="bold">Amount</div>
        <div class="amount-box">{{ frappe.utils.fmt_money(amt, currency=currency) }}</div>
      </div>

      <div class="signature">
        <div class="line"></div>
        <div class="tiny">Authorized Signature</div>
      </div>
    </div>
  </div>

  {# Optional MICR line (needs E-13B font). Replace with your check number if you store it in reference_no. #}
  <!--
  <div style="margin-top:14mm; font-size:16pt; letter-spacing:1px;">
    ⑆{{ routing }}⑆ {{ account_no }} ⑈ {{ doc.reference_no or "" }}
  </div>
  -->
</div>
